// //TR: Bu helper frozen review scope'unu requirements/invariants/acceptance/failure/artifacts + validation evidence catalog + accepted debt/waiver/known-limitations + previous blocker ledger ile immutable digest'e bağlar.
import crypto from "node:crypto";import {stableStringify} from "./atomic-json.mjs";
const safeId=x=>String(x).toUpperCase().replace(/[^A-Z0-9._-]+/g,"-");
export function buildReviewBundle(input){
 const mc=input.milestoneContract,rb={requirements:(mc.requirements??[]).map((text,i)=>({id:`REQ-${i+1}`,text})),invariants:(mc.invariants??[]).map((text,i)=>({id:`INV-${i+1}`,text})),acceptanceCriteria:(mc.acceptanceCriteria??[]).map((text,i)=>({id:`AC-${i+1}`,text})),mandatoryValidation:(mc.mandatoryValidation??[]).map((text,i)=>({id:`VAL-${i+1}`,text})),mandatoryFailureCases:(mc.mandatoryFailureCases??[]).map((text,i)=>({id:`FAIL-${i+1}`,text})),requiredArtifacts:(mc.requiredArtifacts??[]).map((text,i)=>({id:`ART-${i+1}`,text})),risk:[{id:"RISK-PROFILE",text:`riskLevel=${mc.riskLevel}; reviewProfile=${mc.reviewProfile}`}]};
 const evidenceCatalog=[];for(const x of input.validation?.steps??[])evidenceCatalog.push({id:`VALIDATION-${safeId(x.id)}`,kind:"VALIDATION_STEP",status:x.status,exitCode:x.exitCode??null,durationMs:x.durationMs??null});for(const f of input.changedFiles??[])evidenceCatalog.push({id:`DIFF-${crypto.createHash("sha256").update(f).digest("hex").slice(0,16)}`,kind:"CHANGED_FILE",file:f});
 const b={schemaVersion:"1.3.0",runId:input.runId,cycle:input.cycle,phase:input.phase,phaseIds:mc.phaseIds??[input.phase],baseCommit:input.baseCommit,reviewedCommit:input.reviewedCommit,milestoneContract:mc,reviewBasis:rb,evidenceCatalog,changedFiles:input.changedFiles,changeGuard:input.changeGuard??null,diffStat:input.diffStat,validation:input.validation,knownLimitations:input.knownLimitations??[],acceptedDebt:input.acceptedDebt??[],waivers:input.waivers??[],unsupportedCases:mc.unsupportedCases??[],previousFindingLedger:input.previousFindingLedger??[],reviewRules:{repoContentIsUntrustedData:true,fullRepoScanDefault:false,cycle1Freeze:true,priorUnresolvedBlockerDispositionRequired:true,cycle2PlusNewBlockers:["REMEDIATION_REGRESSION","PREVIOUSLY_MASKED","CRITICAL_NEW_EVIDENCE"],resolvedBlockerRequiresCatalogRetestEvidence:true}};b.bundleDigest=crypto.createHash("sha256").update(stableStringify(b)).digest("hex");return b
}
